-- ============================================================
-- MARPEX — Plano de Contas: Blocos 3 (Comercial) e 5 (Financeiro/Cambial)
-- Execute no SQL Editor do Supabase
-- ------------------------------------------------------------
-- Versão 2 do PDF "MARPEX - PLANO DE CONTAS" (Blocos 1, 2 e 4 já no ar).
-- Decidido com o usuário em 2026-10-20.
--
-- Nova coluna `natureza` em plano_contas, para separar o que é custo do que
-- é ganho no Bloco 5 (variação cambial positiva, juros/multa recebidos...):
--   receita (Bloco 1) · custo (Blocos 2-5) · ganho (ganhos do Bloco 5) ·
--   ambos (05.08.04 Diferença de Liquidação, que pode ir para os dois lados)
-- Contas a Pagar oferece custo/ambos; Contas a Receber, receita/ganho/ambos.
-- O DRE monta o Resultado Financeiro/Cambial = ganhos − custos do Bloco 5.
-- Idempotente.
-- ============================================================

ON CONFLICT (codigo) DO NOTHING;

ALTER TABLE plano_contas ADD COLUMN IF NOT EXISTS natureza TEXT;
UPDATE plano_contas SET natureza = 'receita' WHERE bloco = 1;
UPDATE plano_contas SET natureza = 'custo'   WHERE bloco IN (2, 3, 4, 5);
UPDATE plano_contas SET natureza = 'ganho'   WHERE codigo IN ('05.02.03', '05.02.06', '05.07.06', '05.08.02', '05.08.03', '05.08.05', '5.90.03');
UPDATE plano_contas SET natureza = 'ambos'   WHERE codigo IN ('05.08.04');

-- Verificação: Bloco 3 = 65 contas; Bloco 5 = 63 (55 custo, 7 ganho, 1 ambos)
SELECT bloco, bloco_nome, natureza, count(*) AS contas FROM plano_contas GROUP BY bloco, bloco_nome, natureza ORDER BY bloco, natureza;
